import{_ as a,o,c as t,ag as r}from"./chunks/framework.BPmc_f4o.js";const u=JSON.parse('{"title":"Glossary","description":"Definitions of Muxit-specific terms and concepts.","frontmatter":{"title":"Glossary","description":"Definitions of Muxit-specific terms and concepts."},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md"}'),n={name:"reference/glossary.md"};function i(s,e,c,d,l,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Key terms and concepts used throughout Muxit.</p><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h2><h3 id="action" tabindex="-1">Action <a class="header-anchor" href="#action" aria-label="Permalink to &quot;Action&quot;">​</a></h3><p>A command you can execute on a device through its driver. Actions perform operations like <code>reset</code>, <code>start</code>, <code>stop</code>, <code>snapshot</code>, or <code>home</code>. Called from scripts with <code>dev.reset()</code> or from dashboards with button widgets.</p><h3 id="activity-bar" tabindex="-1">Activity Bar <a class="header-anchor" href="#activity-bar" aria-label="Permalink to &quot;Activity Bar&quot;">​</a></h3><p>The vertical strip of icons on the far left of the Muxit UI. Click an icon to switch between the Explorer, Hardware panel, and AI Chat sidebar. The gear icon at the bottom opens Settings.</p><h3 id="agent" tabindex="-1">Agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;Agent&quot;">​</a></h3><p>An autonomous AI instance that pursues multi-step goals. Agents follow a plan-act-observe-re-plan loop, can react to device events via triggers, and operate within configurable safety boundaries. Configured with <code>.agent.json</code> files in <code>workspace/agents/</code>.</p><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><h3 id="connector" tabindex="-1">Connector <a class="header-anchor" href="#connector" aria-label="Permalink to &quot;Connector&quot;">​</a></h3><p>A configuration file that wraps a <a href="#driver">Driver</a>, <a href="#protocol">Protocol</a>, or <a href="#engine">Engine</a> with friendly settings, custom methods, and computed properties. Connectors live in <code>workspace/connectors/</code> as <code>.js</code> ES module files. The filename becomes the connector name — <code>psu.js</code> creates <code>connector(&quot;psu&quot;)</code>. The leading keyword in the file (<code>driver:</code>, <code>protocol:</code>, or <code>engine:</code>) tells the loader which kind it&#39;s targeting. Omit the keyword (with only standard connector keys present) and the connector becomes a <a href="./drivers/virtual.html">Virtual</a> in-memory store with no hardware behind it.</p><h3 id="connector-browser" tabindex="-1">Connector Browser <a class="header-anchor" href="#connector-browser" aria-label="Permalink to &quot;Connector Browser&quot;">​</a></h3><p>The Hardware panel in the left sidebar. Shows all configured connectors with their live property values, actions, and streams. Used to enable/disable connectors and add new ones.</p><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><h3 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h3><p>A drag-and-drop layout of live widgets that display real-time data from your devices. Dashboards are stored as <code>.dashboard.json</code> files in <code>workspace/dashboards/</code>. Widgets include gauges, charts, sliders, buttons, toggles, video streams, and more.</p><h3 id="driver" tabindex="-1">Driver <a class="header-anchor" href="#driver" aria-label="Permalink to &quot;Driver&quot;">​</a></h3><p>A turnkey integration that owns its own communication path to a single device or class of devices. Drivers can be built-in (TestDevice, Webcam, MqttBridge), JavaScript (<code>.driver.js</code>), Python (<code>.driver.py</code>), or C# DLLs. Drivers expose properties (values you can read/write), actions (commands you can execute), and streams (continuous data). Compare with <a href="#protocol">Protocol</a> (generic wire-format parser, you supply the schema) and <a href="#engine">Engine</a> (compute on other connectors). See <a href="./concepts.html">Concepts — Driver, Protocol, Engine</a> for which to pick.</p><h3 id="driver-proxy" tabindex="-1">Driver Proxy <a class="header-anchor" href="#driver-proxy" aria-label="Permalink to &quot;Driver Proxy&quot;">​</a></h3><p>The <code>c</code> object passed to connector methods and properties. It provides natural property syntax: <code>c.voltage</code> reads a property, <code>c.voltage = 12</code> writes it, <code>c.reset()</code> executes an action. The proxy translates these calls to the underlying driver — or to a <a href="#protocol">Protocol</a> instance when the connector uses <code>protocol:</code> instead of <code>driver:</code>.</p><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E&quot;">​</a></h2><h3 id="engine" tabindex="-1">Engine <a class="header-anchor" href="#engine" aria-label="Permalink to &quot;Engine&quot;">​</a></h3><p>A catalog kind for connectors that <strong>compute on data from other connectors</strong> instead of talking to physical hardware. Vision is the first Engine: it subscribes to a camera connector&#39;s video stream and emits detected-object events. Engines are declared with <code>engine: &quot;&lt;Name&gt;&quot;</code> and a <code>source:</code> field that names another connector. See <a href="./concepts.html">Concepts — Driver, Protocol, Engine</a>.</p><h3 id="eventbus" tabindex="-1">EventBus <a class="header-anchor" href="#eventbus" aria-label="Permalink to &quot;EventBus&quot;">​</a></h3><p>Muxit&#39;s internal pub/sub messaging system. Components communicate through events rather than direct references. Scripts publish events with <code>emit()</code>, subscribe with <code>on()</code>, and the system uses events for state updates, stream data, and log broadcasting.</p><h3 id="explorer" tabindex="-1">Explorer <a class="header-anchor" href="#explorer" aria-label="Permalink to &quot;Explorer&quot;">​</a></h3><p>The file browser sidebar in the Muxit UI. Shows your workspace files organized by type — connectors, scripts, dashboards, agents, drivers, and config. Supports favorites, inline run/stop buttons, and drag-and-drop.</p><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h2><h3 id="mcp-model-context-protocol" tabindex="-1">MCP (Model Context Protocol) <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP (Model Context Protocol)&quot;">​</a></h3><p>A standard protocol for AI tools to interact with external systems. Muxit&#39;s MCP server exposes device control, script execution, and file management as tools that Claude Code, Claude Desktop, and other MCP-compatible AI tools can use.</p><h3 id="mqtt" tabindex="-1">MQTT <a class="header-anchor" href="#mqtt" aria-label="Permalink to &quot;MQTT&quot;">​</a></h3><p>A lightweight messaging protocol used by IoT devices. Devices publish messages to topics and subscribe to receive messages. Muxit&#39;s built-in MqttBridge driver connects to MQTT brokers to read IoT sensor data and send commands.</p><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><h3 id="protocol" tabindex="-1">Protocol <a class="header-anchor" href="#protocol" aria-label="Permalink to &quot;Protocol&quot;">​</a></h3><p>A catalog kind that packages a <strong>reusable wire-format parser</strong> (SCPI, line-text, binary frames) without baking in any specific device. A Protocol-based connector supplies its own <code>connection:</code> block (which Transport to use) plus a <code>schema:</code> block (which commands, lines, or frame fields to expect). Three built-in Protocols ship with Muxit: <code>Scpi</code>, <code>LineText</code>, <code>BinaryStream</code>. Compare with <a href="#driver">Driver</a> (turnkey integration) and <a href="#engine">Engine</a>. See <a href="./concepts.html">Concepts — Driver, Protocol, Engine</a>.</p><h3 id="polling" tabindex="-1">Polling <a class="header-anchor" href="#polling" aria-label="Permalink to &quot;Polling&quot;">​</a></h3><p>The automatic, periodic reading of connector properties. When a property has <code>poll: true</code> (or is listed in the connector&#39;s <code>poll</code> array), Muxit reads it at a fixed interval (default 200ms) and broadcasts changes to dashboards and WebSocket clients.</p><h3 id="property" tabindex="-1">Property <a class="header-anchor" href="#property" aria-label="Permalink to &quot;Property&quot;">​</a></h3><p>A named value on a device that you can read and/or write. Properties have a type (string, int, double, bool, array, object), an access mode (R = read-only, R/W = read-write, W = write-only), and optionally a unit and description.</p><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><h3 id="sandbox" tabindex="-1">Sandbox <a class="header-anchor" href="#sandbox" aria-label="Permalink to &quot;Sandbox&quot;">​</a></h3><p>The restricted execution environment for scripts and connector configs. Code runs in an isolated V8 JavaScript engine with access only to Muxit globals (<code>connector()</code>, <code>log</code>, <code>delay()</code>, etc.) and standard JS built-ins. Filesystem, network, and Node.js APIs are blocked.</p><h3 id="script" tabindex="-1">Script <a class="header-anchor" href="#script" aria-label="Permalink to &quot;Script&quot;">​</a></h3><p>A sandboxed JavaScript automation program. Scripts control devices, emit events, push data to dashboards, and can make AI calls. Each runs in its own V8 engine as plain top-level code; pressing Stop ends it immediately. Stored as <code>.js</code> files in <code>workspace/scripts/</code>.</p><h3 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h3><p>The current values of all polled properties across all connectors. State is broadcast to WebSocket clients in batched updates every 50ms. Dashboard widgets bind to state values for real-time display.</p><h3 id="stream" tabindex="-1">Stream <a class="header-anchor" href="#stream" aria-label="Permalink to &quot;Stream&quot;">​</a></h3><p>Continuous data emitted by a driver or script. Streams carry high-frequency data like video frames, serial output, or sensor readings. Dashboard canvas and terminal widgets subscribe to streams for real-time display. Scripts emit stream data with <code>stream(connector, name, data)</code>.</p><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h2><h3 id="transport" tabindex="-1">Transport <a class="header-anchor" href="#transport" aria-label="Permalink to &quot;Transport&quot;">​</a></h3><p>A communication layer that moves bytes between Muxit and a device. Three built-in transports cover almost every wire: <strong>TCP</strong> for network devices (LXI instruments, MQTT brokers, ONVIF cameras), <strong>Serial</strong> for RS-232 / USB-to-serial, and <strong>USBTMC</strong> for instruments with a direct USB-B port. Protocol-based connectors pick a Transport via the <code>connection: { type: &quot;tcp&quot; | &quot;serial&quot; | &quot;usbtmc&quot;, ... }</code> block; turnkey Drivers own their Transport internally. See <a href="./concepts.html">Concepts — Driver, Protocol, Engine</a> for how Transports sit under Protocols and Drivers.</p><h2 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W&quot;">​</a></h2><h3 id="widget" tabindex="-1">Widget <a class="header-anchor" href="#widget" aria-label="Permalink to &quot;Widget&quot;">​</a></h3><p>A visual component on a dashboard. Each widget has a type (gauge, chart, slider, button, toggle, etc.), a position on the grid, and a configuration that binds it to connector properties, actions, or streams. Widgets update in real-time.</p><h3 id="workspace" tabindex="-1">Workspace <a class="header-anchor" href="#workspace" aria-label="Permalink to &quot;Workspace&quot;">​</a></h3><p>The <code>workspace/</code> directory that contains all your user files — connectors, scripts, dashboards, agents, drivers, and configuration. This is Muxit&#39;s runtime root. Everything you create and configure lives here, and it&#39;s preserved during updates.</p>',57)])])}const m=a(n,[["render",i]]);export{u as __pageData,m as default};
